<?php get_header(); ?><main class="container content-area py-5"><?php while(have_posts()):the_post(); ?><article <?php post_class('single-article'); ?>><header class="page-heading"><h1><?php the_title(); ?></h1><div class="entry-meta"><?php echo esc_html(get_the_date()); ?></div></header><?php if(has_post_thumbnail())the_post_thumbnail('large',array('class'=>'img-fluid rounded mb-4')); ?><div class="entry-content"><?php the_content(); ?></div></article><?php endwhile; ?></main><?php get_footer(); ?>